import re
from decimal import Decimal, ROUND_HALF_UP

_UNITS = {}
for _names, _secs in [
    (("s", "sec", "secs", "second", "seconds"), 1),
    (("m", "min", "mins", "minute", "minutes"), 60),
    (("h", "hr", "hrs", "hour", "hours"), 3600),
    (("d", "day", "days"), 86400),
    (("w", "wk", "wks", "week", "weeks"), 604800),
]:
    for _n in _names:
        _UNITS[_n] = _secs

_NUM = r"(?:\d+(?:\.\d*)?|\.\d+)"
_COMPONENT = re.compile(r"\s*(" + _NUM + r")\s*([a-zA-Z]+)\s*")
_ISO = re.compile(
    r"P(?:(" + _NUM + r")W)?(?:(" + _NUM + r")D)?"
    r"(?:T(?:(" + _NUM + r")H)?(?:(" + _NUM + r")M)?(?:(" + _NUM + r")S)?)?",
    re.IGNORECASE,
)
_CLOCK = re.compile(r"(\d+):(\d{1,2})(?::(\d{1,2}(?:\.\d+)?))?")


def _round(value: Decimal) -> int:
    return int(value.quantize(Decimal(1), rounding=ROUND_HALF_UP))


def parse_duration(text: str) -> int:
    """Return the duration described by `text` in whole seconds. See README.md."""
    if not isinstance(text, str):
        raise ValueError("duration must be a string")
    s = text.strip()
    if not s:
        raise ValueError("empty duration")

    # Bare integer
    if re.fullmatch(r"\d+", s):
        return int(s)

    # ISO 8601
    if s[0] in "Pp":
        m = _ISO.fullmatch(s)
        if not m or not any(m.groups()) or (s.upper().endswith("T")):
            raise ValueError(f"invalid ISO 8601 duration: {text!r}")
        mults = (604800, 86400, 3600, 60, 1)
        total = sum(
            (Decimal(g) * k for g, k in zip(m.groups(), mults) if g), Decimal(0)
        )
        return _round(total)

    # Clock notation
    m = _CLOCK.fullmatch(s)
    if m:
        a, b, c = m.groups()
        if c is None:
            mm, ss = int(a), Decimal(b)
            if ss >= 60:
                raise ValueError(f"invalid clock duration: {text!r}")
            return _round(mm * 60 + ss)
        hh, mm, ss = int(a), int(b), Decimal(c)
        if mm >= 60 or ss >= 60:
            raise ValueError(f"invalid clock duration: {text!r}")
        return _round(hh * 3600 + mm * 60 + ss)

    # Number+unit components
    pos = 0
    total = Decimal(0)
    count = 0
    while pos < len(s):
        m = _COMPONENT.match(s, pos)
        if not m:
            raise ValueError(f"invalid duration: {text!r}")
        num, unit = m.groups()
        unit_l = unit.lower()
        if unit_l not in _UNITS:
            raise ValueError(f"unknown unit {unit!r} in {text!r}")
        total += Decimal(num) * _UNITS[unit_l]
        count += 1
        pos = m.end()
    if count == 0:
        raise ValueError(f"invalid duration: {text!r}")
    return _round(total)

